function renderTree(items,box,opened,direct=false){let t={};items.forEach(x=>{let c=x.c,a=c.largeCategory||'未分類',b=c.middleCategory||'その他',s=c.smallCategory||'その他',h=c.heading||'';((((t[a]??={})[b]??={})[s]??={})[h]??=[]).push(x)});box.innerHTML='';Object.entries(t).forEach(([a,m])=>{let A=folder(a,'zk-b1 '+(a==='特殊ゆる'?'special':'normal'),opened,a==='特殊ゆる'?'picker-sticky-special':''),ab=A.lastChild;Object.entries(m).forEach(([b,sm])=>{let B=folder(b,'zk-b2',opened,a==='特殊ゆる'&&b==='限定'?'picker-sticky-limited':''),bb=B.lastChild;Object.entries(sm).forEach(([s,hm])=>{if(b==='伝'){let z=document.createElement('div');z.className='zk-head';z.textContent=s;bb.append(z);Object.entries(hm).forEach(([h,list])=>{if(h&&h!=='その他'){let q=document.createElement('div');q.className='zk-head';q.textContent=h;bb.append(q)}let g=document.createElement('div');g.className='zk-grid';list.forEach(x=>g.append(card(x.c,x.i,opened,null,direct)));bb.append(g)});return}let S=s==='その他'?null:folder(s,'zk-b3',opened),sb=S?S.lastChild:bb;Object.entries(hm).forEach(([h,list])=>{if(h&&h!=='その他'){let z=document.createElement('div');z.className='zk-head';z.textContent=h;sb.append(z)}let g=document.createElement('div');g.className='zk-grid';list.forEach(x=>g.append(card(x.c,x.i,opened,null,direct)));sb.append(g)});if(S)bb.append(S)});ab.append(B)});box.append(A)})}
const coopPickerOpenFolders=new Set();
const pickerNav={mode:'category',large:'特殊ゆる',middle:'対戦',small:'国外',scroll:{},query:''};
function pickerCategoryParts(c){const a=c.largeCategory||'未分類',m=c.middleCategory||'その他';if(m==='伝')return{a,m,sm:'__all__',h:c.heading||c.smallCategory||'その他'};return{a,m,sm:c.smallCategory||'その他',h:c.heading||''}}
function pickerTree(items){let t={};for(const x of items){const {a,m,sm,h}=pickerCategoryParts(x.c);((((t[a]??={})[m]??={})[sm]??={})[h]??=[]).push(x)}return t}
function pickerKey(){return [pickerNav.large,pickerNav.middle,pickerNav.small].filter(Boolean).join('/')}
function pickerSaveScroll(){const e=$('pickerContent');if(e&&pickerNav.mode==='category')pickerNav.scroll[pickerKey()]=e.scrollTop}
function pickerSelectCategory(a,m,sm=''){pickerSaveScroll();pickerNav.mode='category';pickerNav.large=a;pickerNav.middle=m;pickerNav.small=sm;$('pickerCategorySheet').hidden=true;renderPicker()}
function pickerSelectMode(mode){pickerSaveScroll();if(mode!=='search')$('pickerSearch').value='';if(mode==='filter')pickerFilter.view='form';pickerNav.mode=mode;renderPicker()}
/* 「一覧」シート: 大分類ごとのカードに、中分類を1行ずつ並べる。小分類があれば行内のチップで選び、なければ行そのものを押して選ぶ */
function pickerCategoryList(host,t,options={}){const nav=options.nav||pickerNav,select=options.select||pickerSelectCategory;host.replaceChildren();for(const [a,ms] of Object.entries(t)){const group=document.createElement('section'),head=document.createElement('h3'),list=document.createElement('div');group.className='cat-sheet-group';head.className='cat-sheet-group-title';head.textContent=a;list.className='cat-sheet-rows';for(const [m,smalls] of Object.entries(ms)){const names=Object.keys(smalls),single=names.length===1&&(names[0]==='その他'||names[0]==='__all__'),activeMiddle=a===nav.large&&m===nav.middle;if(single){const row=document.createElement('button');row.type='button';row.className='cat-sheet-row cat-sheet-row-button';row.classList.toggle('active',activeMiddle&&nav.small===names[0]);row.innerHTML=`<span class="cat-sheet-row-label">${esc(m)}</span><span class="cat-sheet-row-arrow" aria-hidden="true">›</span>`;row.onclick=()=>select(a,m,names[0]);list.append(row);continue}const row=document.createElement('div'),label=document.createElement('span'),chips=document.createElement('div');row.className='cat-sheet-row';row.classList.toggle('current',activeMiddle);label.className='cat-sheet-row-label';label.textContent=m;chips.className='cat-sheet-chips';for(const sm of names){const chip=document.createElement('button');chip.type='button';chip.className='cat-sheet-chip';chip.textContent=sm==='__all__'?'すべて':sm;chip.classList.toggle('active',activeMiddle&&sm===nav.small);chip.onclick=()=>select(a,m,sm);chips.append(chip)}row.append(label,chips);list.append(row)}group.append(head,list);host.append(group)}}
const zukanNav={mode:'category',large:'特殊ゆる',middle:'対戦',small:'国外',scroll:{},query:''};
function zukanKey(){return [zukanNav.large,zukanNav.middle,zukanNav.small].filter(Boolean).join('/')}
function zukanSaveScroll(){zukanNav.scroll[zukanKey()]=window.scrollY}
function zukanSelectCategory(a,m,sm=''){zukanSaveScroll();zukanNav.large=a;zukanNav.middle=m;zukanNav.small=sm;$('zukanCategorySheet').hidden=true;renderZukan();requestAnimationFrame(()=>window.scrollTo(0,zukanNav.scroll[zukanKey()]||0))}
/* キャラ一覧ナビ(共通部品): 分類タブ・カード一覧・モード切替タブ。
   図鑑(zukanView)とキャラ選択(pickerView)は同じ関数・同じ .char-* クラスで描画する。見た目や並びを変えるときはここだけ直す。 */
function renderCategoryNav(v,items){const nav=v.nav,t=pickerTree(items),larges=Object.keys(t);if(!t[nav.large])nav.large=larges.includes('通常ゆる')?'通常ゆる':larges[0]||'';const middles=Object.keys(t[nav.large]||{});if(!middles.includes(nav.middle))nav.middle=middles[0]||'';const smalls=Object.keys(t[nav.large]?.[nav.middle]||{});if(!smalls.includes(nav.small))nav.small=smalls[0]||'';const firstSmall=(a,m)=>Object.keys(t[a]?.[m]||{})[0]||'',chip=(label,active,onclick,cls='')=>{const b=document.createElement('button');b.type='button';b.textContent=label;if(cls)b.className=cls;b.classList.toggle('active',active);b.onclick=onclick;return b};$(v.ids.large).replaceChildren(...larges.map(a=>chip(a,a===nav.large,()=>{const m=Object.keys(t[a]||{})[0]||'';v.select(a,m,firstSmall(a,m))})));$(v.ids.middle).replaceChildren(...middles.map(m=>chip(m,m===nav.middle,()=>v.select(nav.large,m,firstSmall(nav.large,m)))),chip('一覧',false,()=>{$(v.ids.sheet).hidden=false},'char-all-categories'));const visible=smalls.filter(x=>x!=='__all__'),small=$(v.ids.small);small.hidden=visible.length<2;small.replaceChildren(...visible.map(sm=>chip(sm,sm===nav.small,()=>v.select(nav.large,nav.middle,sm))));pickerCategoryList($(v.ids.sheetBody),t,{nav,select:v.select})}
function renderCategoryItems(v,items){const nav=v.nav,heads=pickerTree(items)[nav.large]?.[nav.middle]?.[nav.small]||{},box=$(v.ids.box),legend=nav.small==='__all__',seen=new Set();let count=0;box.replaceChildren();for(const [heading,list] of Object.entries(heads)){if(heading&&(legend||heading!=='その他')){const h=document.createElement('h3');h.className='char-item-heading';h.textContent=heading;box.append(h)}const grid=document.createElement('div');grid.className='zk-grid char-category-grid';for(const x of list){const key=characterKey(x.c)||String(x.i);if(seen.has(key))continue;seen.add(key);grid.append(card(x.c,x.i,v.inPicker,null,v.inPicker));count++}box.append(grid)}if(!count)box.innerHTML='<p class="picker-empty">該当するキャラがいません</p>';$(v.ids.path).textContent=[nav.large,nav.middle,!legend&&nav.small&&nav.small!=='その他'?nav.small:''].filter(Boolean).join(' ＞ ');$(v.ids.count).textContent=count+'体'}
function renderModeTabs(tabs,current,select,isHidden=()=>false){tabs.querySelectorAll('button').forEach(b=>{const mode=b.dataset.mode;b.hidden=isHidden(mode);b.classList.toggle('active',mode===current);b.onclick=()=>select(mode)})}
const zukanView={nav:zukanNav,inPicker:false,select:(a,m,sm)=>zukanSelectCategory(a,m,sm),ids:{large:'zukanLargeTabs',middle:'zukanMiddleChips',small:'zukanSmallChips',sheet:'zukanCategorySheet',sheetBody:'zukanCategorySheetBody',box:'zkBox',path:'zukanCurrentPath',count:'zukanCurrentCount'}};
const pickerView={nav:pickerNav,inPicker:true,select:(a,m,sm)=>pickerSelectCategory(a,m,sm),ids:{large:'pickerLargeTabs',middle:'pickerMiddleChips',small:'pickerSmallChips',sheet:'pickerCategorySheet',sheetBody:'pickerCategorySheetBody',box:'pickerBox',path:'pickerCurrentPath',count:'pickerCurrentCount'}};
function pickerModes(){const enemy=!!(document.getElementById('page-coop')?.classList.contains('active')&&typeof coopPickerTarget!=='undefined'&&coopPickerTarget?.type==='deck');if(pickerNav.mode==='enemy'&&!enemy)pickerNav.mode='category';renderModeTabs($('pickerModeTabs'),pickerNav.mode,pickerSelectMode,mode=>mode==='enemy'&&!enemy)}

function folder(name,cls,o,stickyClass=''){let w=document.createElement('div'),b=document.createElement('button'),d=document.createElement('div'),a=document.createElement('span'),coopOpen=typeof coopPickerTarget!=='undefined'&&coopPickerTarget&&coopPickerOpenFolders.has(name);o=!!o||coopOpen;w.className='zk-l1';b.className=cls+(stickyClass?' '+stickyClass:'');a.textContent=o?'▼':'▶';d.className='zk-body'+(o?' open':'');b.append(document.createTextNode(name),a);b.onclick=()=>{let x=d.classList.toggle('open');a.textContent=x?'▼':'▶';if(typeof coopPickerTarget!=='undefined'&&coopPickerTarget){if(x)coopPickerOpenFolders.add(name);else coopPickerOpenFolders.delete(name)}syncPickerPinnedTags()};w.append(b,d);return w}
function card(c,i,p,label=null,direct=false){let b=document.createElement('button'),im=document.createElement('img'),sm=document.createElement('small');b.className='zk-card';b.dataset.charIndex=String(i);im.loading='lazy';im.decoding='async';im.width=64;im.height=64;im.src=c.imageUrl||'';sm.textContent=label??c.name??'';b.append(im,sm);let wrap=document.createElement('div');wrap.className='zk-card-wrap';wrap.append(b,favoriteStar(c));b.onclick=()=>{if(direct){current=i;fromPicker=true;if(typeof coopPickerTarget!=='undefined'&&coopPickerTarget){chooseCoopCharacter(c);return}choose('picker');return}let box=b.closest('#zkBox,#zkFilteredBox'),order=box?[...box.querySelectorAll('.zk-card[data-char-index]')].map(x=>Number(x.dataset.charIndex)):null;openDetail(i,p,order&&order.length?order:null)};return wrap}
// キャラ画像の右上の星。押すとお気に入りに登録/解除する(カードを開く・選ぶ動作とは別のボタン)
function favoriteStar(c){let s=document.createElement('button');s.type='button';s.className='zk-fav';s.dataset.favKey=characterKey(c);s.onclick=e=>{e.stopPropagation();toggleTemporary(c)};syncFavoriteStar(s);return s}
function syncFavoriteStar(s){let on=tempCharacters.includes(s.dataset.favKey);s.textContent=on?'★':'☆';s.classList.toggle('active',on);s.setAttribute('aria-pressed',String(on));s.setAttribute('aria-label',on?'お気に入りから外す':'お気に入りに追加')}
function skillEffectsOf(c){return Array.isArray(c?.details?.skillEffects)?c.details.skillEffects:[]}
function pickerSkillAllowed(c,purpose=pickerPurpose,role=pickerRole){if(purpose==='coopDeckRestricted')return skillEffectsOf(c).some(e=>['攻撃力アップ','連撃','全体攻撃','短縮'].includes(en(e)));if(purpose!=='skill')return true;let allowed=role==='attacker'?new Set(['攻撃力アップ','連撃','全体攻撃']):new Set(['シールド','回復','集中','かわす']);return skillEffectsOf(c).some(e=>allowed.has(en(e)))}
function pickerSource(items){return items.filter(x=>pickerSkillAllowed(x.c))}
function skillAttrOrder(value){let s=canon(value);if(!s||['全','全員','味方全員','敵全員','すべて'].includes(s))return 0;if(s.includes('火'))return 1;if(s.includes('水'))return 2;if(s.includes('風'))return 3;return 4}
function skillRelationAttrs(e){let ally=e?.applierAttribute??e?.applier??e?.['適用者']??'',enemy=e?.targetAttribute??e?.target??e?.['対象者']??'';return [skillAttrOrder(ally),skillAttrOrder(enemy)]}
function skillTypeOrder(e){let n=en(e),order={'連撃':4,'全体攻撃':5,'シールド':6,'回復':7,'色変':8,'短縮':9,'遅延':10,'集中':11,'かわす':12};if(n!=='攻撃力アップ')return order[n]??99;let applier=String(e?.applierAttribute??e?.applier??e?.['適用者']??''),target=String(e?.targetAttribute??e?.target??e?.['対象者']??'');if(/自身|自分/.test(applier)||/自身|自分/.test(target))return 3;if(/全員|味方全員/.test(applier)||/全員|味方全員/.test(target))return 2;return 1}
function skillSortKey(c){let es=skillEffectsOf(c);if(!es.length)return [0,0,0];let best=null;for(let e of es){let type=skillTypeOrder(e),attrs=skillRelationAttrs(e),key=type===9?[type,attrs[1],attrs[0]]:[type,attrs[0],attrs[1]];if(!best||key.some((v,i)=>v!==best[i]&&v<best[i]&&key.slice(0,i).every((x,j)=>x===best[j])))best=key}return best||[99,4,4]}
function characterIdOrder(x){let v=Number(x?.c?.id??x?.c?.details?.id);return Number.isFinite(v)?v:Number.MAX_SAFE_INTEGER}
function compareSkillTurn(a,b){let at=Number(a.c.details?.skillTurn),bt=Number(b.c.details?.skillTurn);at=Number.isFinite(at)?at:Number.MAX_SAFE_INTEGER;bt=Number.isFinite(bt)?bt:Number.MAX_SAFE_INTEGER;if(at!==bt)return at-bt;let ak=skillSortKey(a.c),bk=skillSortKey(b.c);for(let i=0;i<ak.length;i++)if(ak[i]!==bk[i])return ak[i]-bk[i];return a.i-b.i}
/* キャラ絞り込み(共通部品)
   図鑑とキャラ選択(計算機・協力)は同じ characterFilterMarkup / createCharacterFilter を使う。
   見た目や項目を変えるときはここと catalog.css の絞り込みの章だけを直せば、全画面に同時に反映される。 */
function characterFilterMarkup(p){return `<section class="zukan-filter char-filter" id="${p}Filter"><div class="zukan-filter-header"><div><small>FILTER</small><h2>キャラを絞り込む</h2><p>条件を組み合わせて、表示するキャラを探します。</p></div><button id="${p}FilterClear" class="zukan-filter-reset" type="button">すべて初期化</button></div><div class="zukan-filter-grid"><section class="filter-card"><h3><span>01</span>基本条件</h3><fieldset class="multi-filter attribute-filter"><legend>属性</legend><div class="segmented-switch" id="${p}AttributeModeSwitch"><label><input type="radio" name="${p}AttributeMode" value="include" checked><span>含む</span></label><label><input type="radio" name="${p}AttributeMode" value="exact"><span>一致</span></label></div><div class="check-options attribute-options"><label><input type="checkbox" name="${p}Attribute" value="火"><span>火</span></label><label><input type="checkbox" name="${p}Attribute" value="水"><span>水</span></label><label><input type="checkbox" name="${p}Attribute" value="風"><span>風</span></label><label class="attribute-exact-only"><input type="checkbox" name="${p}Attribute" value="火水"><span>火水</span></label><label class="attribute-exact-only"><input type="checkbox" name="${p}Attribute" value="水風"><span>水風</span></label><label class="attribute-exact-only"><input type="checkbox" name="${p}Attribute" value="風火"><span>風火</span></label><label class="attribute-exact-only"><input type="checkbox" name="${p}Attribute" value="全"><span>全属性</span></label></div></fieldset><fieldset class="multi-filter"><legend>レア</legend><div class="check-options"><label><input type="checkbox" name="${p}Rare" value="N"><span>N</span></label><label><input type="checkbox" name="${p}Rare" value="R"><span>R</span></label><label><input type="checkbox" name="${p}Rare" value="CR"><span>CR</span></label><label><input type="checkbox" name="${p}Rare" value="ZR"><span>ZR</span></label><label><input type="checkbox" name="${p}Rare" value="MZR"><span>MZR</span></label><label><input type="checkbox" name="${p}Rare" value="伝"><span>伝</span></label></div></fieldset><div class="range-row"><div class="range-label"><b>Cost</b><small>最小～最大</small></div><div class="stepper" data-stepper="${p}CostMin"><button type="button" data-delta="-1">−</button><input id="${p}CostMin" type="number" inputmode="numeric" min="0" placeholder="下限なし"><button type="button" data-delta="1">＋</button></div><span>～</span><div class="stepper" data-stepper="${p}CostMax"><button type="button" data-delta="-1">−</button><input id="${p}CostMax" type="number" inputmode="numeric" min="0" placeholder="上限なし"><button type="button" data-delta="1">＋</button></div></div></section><section class="filter-card"><h3><span>02</span>分類</h3><div class="category-filter-grid pill-select-grid"><label>大分類<select id="${p}LargeCategory" data-multi="1"><option value="">すべて</option></select></label><label>中分類<select id="${p}MiddleCategory" data-multi="1"><option value="">すべて</option></select></label><label>小分類<select id="${p}SmallCategory" data-multi="1"><option value="">すべて</option></select></label><label>見出し<select id="${p}HeadingCategory" data-multi="1"><option value="">すべて</option></select></label></div></section><section class="filter-card filter-card-wide"><h3><span>03</span>スキル条件</h3><fieldset class="multi-filter skill-filter"><legend>ゆるスキル</legend><div class="check-options"><label><input type="checkbox" name="${p}Skill" value="攻撃力アップ"><span>攻撃</span></label><label><input type="checkbox" name="${p}Skill" value="連撃"><span>連続</span></label><label><input type="checkbox" name="${p}Skill" value="全体攻撃"><span>全体</span></label><label><input type="checkbox" name="${p}Skill" value="シールド"><span>シールド</span></label><label><input type="checkbox" name="${p}Skill" value="回復"><span>回復</span></label><label><input type="checkbox" name="${p}Skill" value="蘇生"><span>蘇生</span></label><label><input type="checkbox" name="${p}Skill" value="色変"><span>変化</span></label><label><input type="checkbox" name="${p}Skill" value="短縮"><span>短縮</span></label><label><input type="checkbox" name="${p}Skill" value="遅延"><span>遅延</span></label><label><input type="checkbox" name="${p}Skill" value="かばう"><span>かばう</span></label><label><input type="checkbox" name="${p}Skill" value="かわす"><span>かわす</span></label></div></fieldset><div class="skill-detail-filters"><fieldset class="multi-filter"><legend>効果適用者</legend><div id="${p}SkillApplierOptions" class="check-options"></div></fieldset><fieldset class="multi-filter"><legend>対象者</legend><div id="${p}SkillTargetOptions" class="check-options"></div></fieldset></div><div class="range-row"><div class="range-label"><b>スキル必要ターン</b><small>最小～最大</small></div><div class="stepper" data-stepper="${p}TurnMin"><button type="button" data-delta="-1">−</button><input id="${p}TurnMin" type="number" inputmode="numeric" min="0" placeholder="下限なし"><button type="button" data-delta="1">＋</button></div><span>～</span><div class="stepper" data-stepper="${p}TurnMax"><button type="button" data-delta="-1">−</button><input id="${p}TurnMax" type="number" inputmode="numeric" min="0" placeholder="上限なし"><button type="button" data-delta="1">＋</button></div></div><div class="range-row"><div class="range-label"><b>スキル継続ターン</b><small>最小～最大</small></div><div class="stepper" data-stepper="${p}DurMin"><button type="button" data-delta="-1">−</button><input id="${p}DurMin" type="number" inputmode="numeric" min="0" placeholder="下限なし"><button type="button" data-delta="1">＋</button></div><span>～</span><div class="stepper" data-stepper="${p}DurMax"><button type="button" data-delta="-1">−</button><input id="${p}DurMax" type="number" inputmode="numeric" min="0" placeholder="上限なし"><button type="button" data-delta="1">＋</button></div></div><section class="skill-effect-amounts"><div class="skill-effect-heading"><b>スキル別の効果量</b><small>選択した数値効果ごとに指定</small></div><p id="${p}EffectEmpty" class="skill-effect-empty">数値効果を持つスキルを選択すると、スキルごとの範囲が表示されます。</p><div id="${p}EffectRows"></div></section></section><section class="filter-card"><h3><span>04</span>並び順</h3><div class="filter-sort-controls pill-select-grid"><label>項目<select id="${p}Sort"><option value="">指定なし</option><option value="hp">HP</option><option value="power">攻撃力</option><option value="total">HP+攻撃力</option><option value="cost">Cost</option><option value="skillTurn">スキル必要ターン</option><option value="rare">レア</option></select></label><label>順序<select id="${p}SortDirection"><option value="desc">降順</option><option value="asc">昇順</option></select></label></div></section></div><div class="zukan-filter-footer"><span id="${p}FilterPreviewCount">全キャラから検索</span><button id="${p}FilterApply" class="char-filter-apply" type="button">この条件でキャラを表示 <span>→</span></button></div></section><section class="zukan-filter-results char-filter-results" id="${p}FilterResults" hidden><div class="filtered-heading"><button id="${p}FilterBack" class="char-filter-back" type="button">← 条件を変更</button><div><small>FILTER RESULT</small><h2>絞り込み結果</h2></div><span id="${p}FilteredCount" class="char-filter-count"></span></div><div id="${p}FilteredBox" class="zk-grid"></div></section>`}
function attributeMatches(value,selected,mode){let cur=canon(value);if(!selected.length)return true;if(mode==='exact')return selected.includes(cur);return selected.some(a=>cur==='全'||cur.includes(a))}
function zkNumericSkillConfig(skill){const map={'攻撃力アップ':{label:'攻撃力アップ',unit:'%',scale:100,step:1},'シールド':{label:'軽減率',unit:'%',scale:100,step:1},'回復':{label:'回復量',unit:'%',scale:100,step:1},'蘇生':{label:'蘇生時HP',unit:'%',scale:100,step:1},'かばう':{label:'軽減率',unit:'%',scale:100,step:1},'かわす':{label:'軽減率',unit:'%',scale:100,step:1},'連撃':{label:'連撃回数',unit:'回',scale:1,step:1},'遅延':{label:'遅延量',unit:'カウント',scale:1,step:1},'短縮':{label:'短縮量',unit:'カウント',scale:1,step:1},'色変':{label:'変化後の属性',type:'attribute',options:['火','水','風','全']}};return map[skill]||null}
function characterSortLabel(c,sort){let d=c.details||{};if(!sort)return c.name||'';if(sort==='hp')return `HP ${Number(d.limitHp??d.hp??0).toLocaleString()}`;if(sort==='power')return `攻撃力 ${Number(d.limitPower??d.power??0).toLocaleString()}`;if(sort==='total')return `HP+攻撃力 ${(Number(d.limitHp??d.hp??0)+Number(d.limitPower??d.power??0)).toLocaleString()}`;if(sort==='cost')return `Cost ${Number(d.cost??0).toLocaleString()}`;if(sort==='skillTurn')return `必要ターン ${Number(d.skillTurn??0).toLocaleString()}`;if(sort==='rare')return `レア ${d.rare||''}`;return c.name||''}
