function move(d){lastDirection=d<0?-1:1;let p=detailOrder.indexOf(current);if(p>=0&&detailOrder.length)openDetail(detailOrder[(p+lastDirection+detailOrder.length)%detailOrder.length],fromPicker,detailOrder)}
function choose(r){if(r==='picker')r=pickerRole;if(fromPicker&&pickerPurpose==='skill'){addBorrowedSkill(r,chars[current]);$('detail').hidden=$('picker').hidden=true;showPage('calculator');return}setCharacter(r,chars[current]);$('detail').hidden=$('picker').hidden=true;showPage('calculator')}
function norm(x){let s=canon(x);return ATTRS.filter(a=>a!=='全').sort((a,b)=>b.length-a.length).find(a=>s.includes(a))||'全'}
function setCharacter(r,c,keep=false){selected[r]=c;if(!keep)skillEnabled[r]=false;let d=c.details||{},p=$(r+'Picker');p.querySelector('.portrait').style.backgroundImage=`url("${String(c.imageUrl||'').replace(/"/g,'')}")`;p.querySelector('strong').textContent=c.name||'';p.title=c.name||'';p.querySelector('small').textContent=[d.rare,canon(d.attribute),d.cost!=null?'Cost '+d.cost:null].filter(Boolean).join(' / ');$(r==='attacker'?'attackerPower':'defenderHp').value=Number(r==='attacker'?(d.limitPower??d.power??0):(d.limitHp??d.hp??0));$(r+'Attribute').value=norm(d.attribute);$(r+'Event').value='1';if(r==='attacker'&&!keep)$('survivalTurns').value='0';$(r+'Skill').textContent=d.skill||'スキルなし';$(r+'SkillBtn').disabled=!d.skill;syncSkill(r);calculate()}


/* お気に入り・共通選択機能 */
function characterKey(c){return String(c?.id??c?.details?.id??c?.name??'')}
function loadTemporaryCharacters(){try{let ids=JSON.parse(localStorage.getItem('eigoTemporaryCharacters')||'[]');tempCharacters=[...new Set((Array.isArray(ids)?ids:[]).map(String))]}catch{tempCharacters=[]}renderTemporaryCharacters()}
function persistTemporaryCharacters(){tempCharacters=[...new Set(tempCharacters.map(String))];localStorage.setItem('eigoTemporaryCharacters',JSON.stringify(tempCharacters));renderTemporaryCharacters();renderPickerTemporary();syncDetailTemporaryButton();document.querySelectorAll('.zk-fav').forEach(syncFavoriteStar)}
function isTemporary(c){return tempCharacters.includes(characterKey(c))}
function toggleTemporary(c){if(!c)return;let k=characterKey(c),i=tempCharacters.indexOf(k);if(i>=0)tempCharacters.splice(i,1);else tempCharacters.push(k);persistTemporaryCharacters()}
function toggleCurrentTemporary(){toggleTemporary(chars[current])}
function syncDetailTemporaryButton(){let b=$('detailTemp'),c=chars[current];if(!b||!c)return;b.textContent=isTemporary(c)?'お気に入りから外す':'お気に入りに追加';b.classList.toggle('danger',isTemporary(c))}
function temporaryEntries(){let set=new Set(tempCharacters),seen=new Set();return chars.map((c,i)=>({c,i})).filter(x=>{let k=characterKey(x.c);if(!set.has(k)||seen.has(k))return false;seen.add(k);return true})}
function renderTemporaryCharacters(){let box=$('tempList');if(!box)return;box.innerHTML='';temporaryEntries().forEach(x=>{let row=document.createElement('div');row.className='temp-item';let cb=document.createElement('input');cb.type='checkbox';cb.value=characterKey(x.c);let open=document.createElement('button');open.type='button';open.className='temp-open';open.dataset.charDrag='temp:'+characterKey(x.c);let im=document.createElement('img');im.src=x.c.imageUrl||'';let name=document.createElement('span');name.textContent=x.c.name||'';open.append(im,name);open.onclick=()=>openDetail(x.i,false,temporaryEntries().map(y=>y.i));let del=document.createElement('button');del.type='button';del.className='mini-reset danger temp-delete';del.textContent='キャラ削除';del.onclick=()=>{tempCharacters=tempCharacters.filter(k=>k!==characterKey(x.c));persistTemporaryCharacters()};row.append(cb,open,del);box.append(row)});$('tempEmpty').hidden=box.children.length>0}
function removeSelectedTemporary(){let values=[...document.querySelectorAll('#tempList input:checked')].map(x=>x.value),set=new Set(values);tempCharacters=tempCharacters.filter(x=>!set.has(x));persistTemporaryCharacters()}
function clearAllTemporary(){tempCharacters=[];persistTemporaryCharacters()}
function renderPickerTemporary(){let box=$('pickerTemporary');if(!box)return;box.innerHTML='';let list=pickerSource(temporaryEntries());$('pickerTemporaryEmpty').hidden=!!list.length;list.forEach(x=>box.append(card(x.c,x.i,true,null,true)))}
function addBorrowedSkill(role,c){borrowedSkills[role].push(c);borrowedEnabled[role].push(false);renderBorrowedSkills(role);calculate()}
function clearBorrowedSkills(role){borrowedSkills[role]=[];borrowedEnabled[role]=[];renderBorrowedSkills(role);calculate()}
function toggleBorrowedSkill(role,index){borrowedEnabled[role][index]=!borrowedEnabled[role][index];renderBorrowedSkills(role);calculate()}
function useAllBorrowed(role){borrowedEnabled[role]=borrowedSkills[role].map(()=>true);renderBorrowedSkills(role);calculate()}
function disableAllBorrowed(role){borrowedEnabled[role]=borrowedSkills[role].map(()=>false);renderBorrowedSkills(role);calculate()}
function deleteBorrowedSkill(role,index){borrowedSkills[role].splice(index,1);borrowedEnabled[role].splice(index,1);renderBorrowedSkills(role);calculate()}
function renderBorrowedSkills(role){let box=$(role+'BorrowedList'),list=borrowedSkills[role];while(borrowedEnabled[role].length<list.length)borrowedEnabled[role].push(false);borrowedEnabled[role].length=list.length;box.innerHTML='';list.forEach((c,i)=>{let row=document.createElement('div');row.className='borrowed-item';let span=document.createElement('span');span.textContent=(c.name||'')+'：'+(c.details?.skill||'スキルなし');let use=document.createElement('button');use.type='button';use.className='mini-reset borrowed-use'+(borrowedEnabled[role][i]?' active':'');use.textContent=borrowedEnabled[role][i]?'スキル解除':'スキル使用';use.onclick=()=>toggleBorrowedSkill(role,i);let del=document.createElement('button');del.type='button';del.className='mini-reset danger borrowed-delete';del.textContent='スキル削除';del.onclick=()=>deleteBorrowedSkill(role,i);row.append(span,use,del);box.append(row)});$(role+'BorrowedCount').textContent=list.length+'体';$(role+'BorrowedActions').hidden=!list.length}
function ensurePickerTools(){let picker=$('picker');if(picker.dataset.toolsReady)return;picker.dataset.toolsReady='1';$('pickerCategorySheetClose').onclick=()=>$('pickerCategorySheet').hidden=true;if($('pickerEnemyToggle'))$('pickerEnemyToggle').onclick=()=>{let body=$('pickerEnemyBody'),open=body.classList.toggle('open');$('pickerEnemyToggle').querySelector('span').textContent=open?'▼':'▶'};for(let role of ['attacker','defender']){$(role+'UseAllBorrowed').onclick=()=>useAllBorrowed(role);$(role+'DisableAllBorrowed').onclick=()=>disableAllBorrowed(role);$(role+'ClearBorrowed').onclick=()=>clearBorrowedSkills(role)}renderBorrowedSkills('attacker');renderBorrowedSkills('defender')}

/* 「使い方」ページの本文。機能を変えたら、ここと app.js の PAGE_HELP(各ページの「使い方」ボタン)を一緒に直す */
function renderComprehensiveHelp(){let box=document.querySelector('#page-help .help-panel');if(box)box.innerHTML=`<small class="page-eyebrow">GUIDE</small><h1>使い方</h1><p class="page-lead">各ページの操作と、計算のしくみをまとめています。各ページの「使い方」ボタンからは、そのページの要点だけを確認できます。</p><nav class="help-index" aria-label="目次"><a href="#help-start">はじめに</a><a href="#help-calc">ダメージ計算機</a><a href="#help-formula">計算のしくみ</a><a href="#help-skill">スキルの扱い</a><a href="#help-zukan">図鑑</a><a href="#help-coop">協力ダメージ計算</a><a href="#help-report">協力報告書</a><a href="#help-data">データの保存</a></nav><section id="help-start"><h2><span class="help-num">01</span>はじめに</h2><div class="help-cards"><button type="button" class="help-card" data-go="calculator"><b>ダメージ計算機</b><span>1対1で、攻撃キャラが攻撃対象を倒せるかを計算します。</span></button><button type="button" class="help-card" data-go="zukan"><b>図鑑</b><span>全キャラを分類・条件・名前から探して、詳しい能力を見ます。</span></button><button type="button" class="help-card" data-go="coop"><b>協力ダメージ計算</b><span>協力の1〜5層の敵を、参加者のデッキで全滅できるかを判定します。</span></button><button type="button" class="help-card" data-go="coop-report"><b>協力報告書作成</b><span>キャラと数値をマス目に並べて、報告用の表を作ります。</span></button></div><h3>メニューと「使い方」ボタン</h3><p>左のメニューでページを切り替えます。PCでは左上の≡を押すと、メニューを「文字あり」と「アイコンだけの細い表示」で切り替えられます(次に開いたときも同じ表示です)。スマホ・タブレットでは≡でメニューを開き、ページを選ぶか、メニューの外を押すと閉じます。各ページの見出しの右にある「使い方」ボタンで、そのページの要点を確認できます。</p><h3>キャラの選び方(全ページ共通)</h3><p>キャラの枠を押すと、キャラ選択の画面が開きます。上のタブで探し方を切り替え、キャラを押すとそのまま決まります。</p><dl class="help-dl"><dt>分類</dt><dd>特殊ゆる・通常ゆるなどの分類から探します。「一覧」で全分類を見渡せます。</dd><dt>お気に入り</dt><dd>お気に入りに登録したキャラから選びます。</dd><dt>ドロップキャラ</dt><dd>協力ダメージ計算の味方を選ぶときだけ出ます。敵として入力したキャラから選べます。</dd><dt>絞り込み</dt><dd>属性・レア・Cost・スキルなどの条件で探します(図鑑と同じ)。</dd><dt>キャラ名で検索</dt><dd>名前の一部で探します。</dd></dl><h3>キャラ画像のドラッグ</h3><p>キャラが入っている枠は、画像を掴んで別の枠へ動かせます。パソコンはマウスを押したまま動かし、スマホは画像を長押ししてから指を動かします。普通に押したときは、今までどおりキャラ選択が開きます。</p><dl class="help-dl"><dt>同じ種類の枠どうし</dt><dd>入れ替わります(計算機の攻撃キャラと攻撃対象キャラ、協力の敵どうし・味方どうし、協力報告書のマスどうし)。協力の敵は無凸HP・属性、味方はPower、報告書は数値も一緒に動きます。</dd><dt>別の種類の枠へ</dt><dd>そのキャラを選んだのと同じように入ります(協力の敵→味方の枠、計算機のキャラ→「他キャラのスキル」の欄など)。元の枠はそのままです。</dd><dt>お気に入りから</dt><dd>右上の「お気に入り」を開き、キャラを各ページの枠へ動かせます。</dd></dl><p>置ける枠は青い枠、置けない枠は赤い点線で表示されます。たとえば協力の味方2〜5枠目に条件に合わないキャラを置こうとしたときや、同じデッキに同じキャラがいるときは置けません。</p><h3>お気に入り</h3><p>図鑑やキャラ選択で、キャラ画像の右上の☆を押すと★になり、お気に入りに登録されます。もう一度押すと外れます。図鑑のキャラ詳細の「お気に入りに追加」でも登録できます。登録したキャラは右上の「お気に入り」に入ります。よく使うキャラを入れておくと、キャラ選択ですぐに呼び出せます。同じキャラは1件にまとまります。</p><h3>キャラ詳細</h3><p>← →(A・D、J・K でも可)で、いま表示している並び順の前後のキャラへ移ります。Space・Enter は直前の操作の繰り返し、Esc は閉じるです。</p></section><section id="help-calc"><h2><span class="help-num">02</span>ダメージ計算機</h2><ol class="help-steps"><li>「攻撃キャラ」と「攻撃対象キャラ」の枠を押して、キャラを選びます。完凸の値があれば完凸Power・完凸HPが、なければ通常の値が入ります。</li><li>イベント補正・解答速度・自力モード・問題レベルを、対戦の状況に合わせます。</li><li>ゆるスキルを使うなら「スキル使用」を押します。ほかのキャラのスキルは「他キャラのスキルを追加」で選び、その行の「スキル使用」を押すと反映されます(追加しただけでは反映されません)。</li><li>入力するたびに、予想ダメージ欄がすぐに計算し直されます。</li></ol><h3>入力する項目</h3><div class="help-table-scroll"><table class="help-table"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>Power / HP</td><td>攻撃側はPower、攻撃対象はHP。キャラを選ぶと自動で入ります。手で変えても構いません。</td></tr><tr><td>属性</td><td>属性相性の計算に使います。キャラを選ぶと自動で入ります。</td></tr><tr><td>イベント補正</td><td>なし ×1.0 / あり ×1.5。別のキャラを選ぶと「なし」に戻ります。</td></tr><tr><td>解答速度</td><td>Excellent ×1.2 / Correct ×1.0</td></tr><tr><td>自力モード</td><td>自力 ×1.2 / 他力 ×1.0</td></tr><tr><td>問題レベル</td><td>小学生 ×1.45、中1 ×1.5、中2 ×1.55、中3 ×1.6、高1 ×1.65、高2 ×1.7、高3 ×1.75、難関 ×1.8</td></tr><tr><td>追加攻撃力増加</td><td>スキル以外で受けている攻撃力アップを%で入れます(最大4つ。入れると次の欄が出ます)。</td></tr><tr><td>追加軽減率</td><td>攻撃対象が受けている軽減を%で入れます(最大6つ)。引き継いだかばうの効果などに使います。</td></tr><tr><td>生存補正 ※</td><td>生き残ったターン数(0〜10)。×1.3のターン数乗が掛かります。</td></tr><tr><td>全体攻撃 ※</td><td>ありにすると×5。スキルの全体攻撃と両方ONでも×5は1回だけです。</td></tr><tr><td>追加連撃効果 ※</td><td>スキル以外の連撃を回数で入れます(最大3つ)。</td></tr><tr><td>追加回復効果 ※</td><td>攻撃対象の回復を%で入れます(最大3つ)。</td></tr></tbody></table></div><p class="help-note">※は「詳細モード」をONにしたときだけ表示・計算されます。OFFにしても入力した値は残ります。</p><h3>結果の見かた</h3><div class="help-table-scroll"><table class="help-table"><thead><tr><th>表示</th><th>意味</th></tr></thead><tbody><tr><td>確定撃破</td><td>乱数で最も低いダメージでも倒せます。</td></tr><tr><td>乱数撃破</td><td>乱数しだいで倒せます。残りHPは「0〜最大の残り」で表示します。</td></tr><tr><td>撃破不可</td><td>最も高いダメージでも倒せません。残りHPを表示します。</td></tr><tr><td>〇〜〇発で撃破</td><td>連撃があり、倒せるときに出ます。何発目で倒れるかです。</td></tr><tr><td>余剰火力</td><td>倒した後に余る連撃の発数とダメージです。属性相性2/3で、攻撃対象のスキルや軽減を除いた純粋な火力で計算します。全体攻撃が掛かっているときは「×全体」が付きます。</td></tr><tr><td>耐久値</td><td>攻撃対象が耐えられるダメージ量です。予想ダメージとそのまま比べられます。</td></tr><tr><td>幽霊攻撃への耐久</td><td>詳細モードのときだけ。幽霊攻撃(1296ダメージ±10%)に何発耐え、何発目で倒されるかです。</td></tr></tbody></table></div><h3>ボタン</h3><dl class="help-dl"><dt>⇄ 攻守を入れ替え</dt><dd>攻撃キャラと攻撃対象キャラを入れ替えます。</dd><dt>キャラ以外リセット</dt><dd>キャラ・Power/HP・属性・イベント補正は残し、ほかの入力を初めの状態に戻します。</dd><dt>キャラ削除</dt><dd>キャラとPower/HPなども含めて消します。</dd><dt>全リセット</dt><dd>計算機のすべてを初めの状態に戻します。</dd><dt>計算結果を保存</dt><dd>今の入力と結果を「計算履歴」に保存します(最大100件、古いものから消えます)。履歴の「計算機に反映」で、その時の入力に戻せます。</dd><dt>スクショ用画面を開く</dt><dd>入力条件と結果を1画面にまとめて表示します。端末のスクリーンショットで共有してください。</dd></dl></section><section id="help-formula"><h2><span class="help-num">03</span>計算のしくみ(ダメージ計算機)</h2><h3>ダメージ</h3><p class="formula"><code>攻撃の基礎値 = Power × 解答速度 × 自力モード × イベント補正 × 問題レベル × 生存補正 × 追加攻撃力の倍率 × スキルの攻撃力倍率 × 0.75</code></p><p class="formula"><code>1発のダメージ = 攻撃の基礎値 × 軽減の倍率 × 全体攻撃(×5) × 属性相性</code></p><p class="formula"><code>合計 = 1発のダメージ × 攻撃回数</code><br><code>表示するダメージ = 合計の90%〜110%(小数点以下切り捨て)</code></p><p>攻撃力アップは足し算ではなく掛け算です。80%と50%なら 1.8 × 1.5 = 2.7倍 になります。</p><h3>軽減</h3><p>追加軽減率と、条件を満たしたシールド・かばう・かわすを大きい順に並べ、2つ目以降は効きを弱めて掛け合わせます。</p><p class="formula"><code>i番目(0から数える)の実際の軽減率 = 軽減率 × 3 ÷ (2 × (i + 1) + 1)</code><br><code>軽減の倍率 = (1 − 実際の軽減率) をすべて掛けたもの</code></p><p>1つ目はそのまま、2つ目は3/5、3つ目は3/7、4つ目は1/3、5つ目は3/11、6つ目は3/13の強さで効きます。</p><h3>連撃</h3><p class="formula"><code>攻撃回数 = 1 + (各連撃の回数 − 1) の合計</code></p><p>3回・2回・5回の連撃なら 1 + 2 + 1 + 4 = 8回 です。</p><h3>回復と耐久値</h3><p>回復は、完凸時の最大HPまでは等倍、それを超えた分は1/2として足します。</p><p class="formula"><code>耐久値 = (HP × イベント補正 + 回復) ÷ 軽減の倍率</code></p><h3>属性相性</h3><div class="help-table-scroll"><table class="help-table"><thead><tr><th>攻撃＼防御</th><th>火</th><th>水</th><th>風</th><th>火水</th><th>水風</th><th>風火</th><th>全</th></tr></thead><tbody><tr><th>火</th><td>2/3</td><td>1/3</td><td>1</td><td>1/2</td><td>2/3</td><td>5/6</td><td>2/3</td></tr><tr><th>水</th><td>1</td><td>2/3</td><td>1/3</td><td>5/6</td><td>1/2</td><td>2/3</td><td>2/3</td></tr><tr><th>風</th><td>1/3</td><td>1</td><td>2/3</td><td>2/3</td><td>5/6</td><td>1/2</td><td>2/3</td></tr><tr><th>火水</th><td>5/6</td><td>1/2</td><td>2/3</td><td>2/3</td><td>7/12</td><td>3/4</td><td>2/3</td></tr><tr><th>水風</th><td>2/3</td><td>5/6</td><td>1/2</td><td>3/4</td><td>2/3</td><td>7/12</td><td>2/3</td></tr><tr><th>風火</th><td>1/2</td><td>2/3</td><td>5/6</td><td>7/12</td><td>3/4</td><td>2/3</td><td>2/3</td></tr><tr><th>全</th><td>2/3</td><td>2/3</td><td>2/3</td><td>2/3</td><td>2/3</td><td>2/3</td><td>2/3</td></tr></tbody></table></div></section><section id="help-skill"><h2><span class="help-num">04</span>スキルの扱い</h2><ul><li><b>適用者・対象者の属性</b>: 「火」なら、火・火水・風火・全属性のキャラに当てはまります(水・風も同じ)。味方の条件は効果を受けるキャラ、敵の条件は相手キャラの今の属性で判定し、両方あれば両方を満たしたときだけ効きます。</li><li><b>自身・自分</b>: スキルを持つキャラ本人にだけ効きます。他キャラのスキルとして追加した場合は、選んでいるキャラには効きません(かばう・かわすの軽減は例外で、追加した分もすべて効きます)。</li><li><b>リーダー・味方全員</b>: 選んでいるキャラに効きます。</li><li><b>色変</b>: 先に属性を変え、変わった後の属性で他の効果の条件を判定します。</li><li><b>効果の種類</b>: 攻撃力アップは掛け算、連撃は回数を足し算、全体攻撃は×5を1回、シールド・かばう・かわすは軽減、回復はHPに足します。短縮・遅延・蘇生は表示だけで、ダメージには影響しません。</li></ul><h3>他キャラのスキルで選べるキャラ</h3><p>攻撃キャラ側は攻撃力アップ・連撃・全体攻撃のどれか、攻撃対象側はシールド・回復・かばう・かわすのどれかを持つキャラだけが出ます。同じキャラを何体でも追加できます。</p></section><section id="help-zukan"><h2><span class="help-num">05</span>図鑑</h2><h3>分類</h3><p>上の段で大分類(特殊ゆる・通常ゆる)と中分類、下の段で小分類を選びます。「一覧」を押すと全分類が並び、そこから直接選べます。</p><h3>絞り込み</h3><p>条件を選ぶと、下に該当数が出ます。「この条件でキャラを表示」で結果に切り替わり、「← 条件を変更」で戻ります。「すべて初期化」で条件を消せます。</p><dl class="help-dl"><dt>属性</dt><dd>「含む」は複合属性も含めて探し、「一致」は選んだ属性とぴったり同じキャラだけを探します。</dd><dt>レア</dt><dd>N・R・CR・ZR・MZR・伝</dd><dt>Cost・スキル必要ターン・スキル継続ターン</dt><dd>最小〜最大の範囲。スキル必要ターンはスキルを使えるまでのターン数、スキル継続ターンは効果が続くターン数です(回復など一瞬で終わる効果は、継続ターンを指定すると対象外になります)。− ＋ は長押しで連続して変わります。</dd><dt>ゆるスキル</dt><dd>効果の種類。数値のある効果を選ぶと、効果量の範囲も指定できます。</dd><dt>効果適用者・対象者</dt><dd>スキルが誰に効くか、どの敵に効くかで絞ります。</dd><dt>分類</dt><dd>大分類・中分類・小分類・見出しを、それぞれ複数選べます。</dd><dt>並び順</dt><dd>HP・攻撃力・HP+攻撃力・Cost・スキル必要ターン・レア。並べ替え中は、カードの下に名前の代わりにその値を出します。</dd></dl><p>同じ項目の中で複数選ぶと「どれか」、別の項目どうしは「すべて」に当てはまるキャラが出ます。同じキャラは1体だけ表示します。</p><p>スキル必要ターン順では、ターン数が同じキャラを、スキルの種類(スキルなし → 攻撃力アップ → 連撃 → 全体 → シールド → 回復 → 色変 → 短縮 → 遅延 → かばう → かわす)と、属性の条件(全 → 火 → 水 → 風)の順に並べます。そのほかの並び順で値が同じときはキャラ番号順です。</p><h3>キャラ名で検索</h3><p>名前の一部で探します。全角・半角の違いと空白は気にしなくて大丈夫です。結果は分類の見出しごとに表示します。</p></section><section id="help-coop"><h2><span class="help-num">06</span>協力ダメージ計算</h2><h3>考え方</h3><p>協力では、参加する人がそれぞれ5体のデッキで出撃します。このページでは、各デッキの1枠目が1層、2枠目が2層…5枠目が5層を攻撃するとして、入力したデッキ全体で1〜5層の敵(各層3体)を全滅できるかを判定します。</p><h3>手順</h3><ol class="help-steps"><li>1〜5層の左・真ん中・右の枠を押して、敵キャラを選びます。各層は1体1行の表になっていて、属性と、層の倍率を掛けた後のHPが自動で出ます。</li><li>味方デッキの上の操作欄で、「自力」(自力/他力)と「問題レベル」を合わせます。</li><li>味方デッキに、参加する人のデッキを入れます。1つ入れると次のデッキ欄が出ます(最大5デッキ)。</li><li>「手動デッキ判定」で結果を見ます。</li></ol><p>PCでは敵と味方デッキを左右に並べ、それぞれの欄の中でスクロールします。手動デッキ判定の結果は、味方デッキ欄の下端に常に表示されます。</p><h3>判定の意味</h3><p>入力したデッキが<b>どの順番で出撃しても</b>、各キャラが<b>層の3体のどれを狙っても</b>全滅できるかを、すべての組み合わせで調べます。攻撃はまだ倒れていない敵にだけ向かいます。</p><dl class="help-dl"><dt>確定撃破</dt><dd>すべての組み合わせで全滅できます。</dd><dt>ランダム撃破</dt><dd>出撃順や狙う敵によっては全滅できません。失敗する層と、その時の出撃順・攻撃先の例を表示します。</dd><dt>撃破不可</dt><dd>どの組み合わせでも全滅できません。</dd></dl><h3>敵のHP</h3><p class="formula"><code>敵のHP = 無凸HP × 層の倍率</code>(1層 ×2.5、2層 ×2.5、3層 ×8、4層 ×10、5層 ×50)</p><p>「ゆる神の像＆ピヨか？」だけは、さらに×5になります。</p><h3>味方のダメージ</h3><p class="formula"><code>1発のダメージ = Power × 0.81 × 自力モード(自力 ×1.2 / 他力 ×1.0) × 問題レベル × 属性相性 × 攻撃力アップ</code></p><p>問題レベルの倍率は 小学生 ×1.1、中1 ×1.2、中2 ×1.3、中3 ×1.4、高1 ×1.5、高2 ×1.6、高3以上 ×1.99 です。Powerは完凸Powerを使います(詳細モードでは手入力した値)。連撃は回数分攻撃し、全体攻撃が掛かると層の3体すべてに当たります。</p><h3>スキルの発動</h3><ul><li>1枠目は必要ターン0のスキル、2枠目は1以下、3枠目は2以下…と、枠が進むほど重いスキルが使えます。</li><li>短縮が発動すると、<b>同じ枠にいる他のデッキの</b>対象キャラが、その分だけ早くスキルを使えます(後の枠には効きません)。</li><li>継続ターンのある効果は、後の枠にも掛かります。味方全員・属性指定の効果は他のデッキにも掛かり、「自身」の効果は同じデッキの後の枠にだけ掛かります。</li><li>判定はキャラの構造化されたスキルデータを使います。各キャラの「スキル確認」で、その枠に掛かっているスキルと発動元を確認できます。</li></ul><h3>味方に選べるキャラ</h3><p>2〜5枠目に選べるのは、攻撃力アップ・連撃・全体攻撃・短縮のスキルを持つキャラだけです。キャラ選択の「ドロップキャラ」から、敵として入れたキャラも選べます。</p><h3>デッキの操作</h3><dl class="help-dl"><dt>キャラの右上の×</dt><dd>その枠のキャラを外します。</dd><dt>デッキ1のみ自動入力</dt><dd>各層の真ん中の敵キャラを、デッキ1の1〜5枠に入れます。</dd><dt>コピー / ペースト</dt><dd>「コピー」を押すと、他のデッキに「ペースト」が出て貼り付けられます。</dd><dt>デッキ削除</dt><dd>そのデッキの中身を消します。</dd><dt>ドロップキャラ以外削除</dt><dd>味方デッキから、敵として入力したキャラ以外を消します。</dd><dt>全デッキリセット</dt><dd>味方デッキだけを空にします(敵は残ります)。</dd><dt>全リセット</dt><dd>敵・味方・設定をすべて初めの状態に戻します。</dd></dl><h3>詳細モード</h3><p>ONにすると、敵の表に「無凸HP」「属性」の入力欄が加わり、味方の各キャラの下にPowerの入力欄が出ます。また、味方デッキの上の操作欄に「デッキ提案」が出ます。OFFに戻しても、入力した値は残ります。</p><h3>デッキ提案(詳細モード)</h3><ol class="help-steps"><li>敵を入れ、必要なら固定したい味方を先に入れておきます。入力済みの枠はそのまま使い、空いている枠だけを探します。</li><li>「攻略デッキ数」(3〜5)を選び、「デッキ提案」を押します。</li><li>「計算開始」か「詳細計算を開始」を選びます。詳細計算は2枠目以降の候補を広げて、より多くの組み合わせを調べます。</li><li>結果の提案デッキは「手動デッキへ追加」で味方デッキに入れられます。枠別キャラ使用数で、よく使われるキャラも確認できます。</li></ol><p class="help-note">計算には時間がかかり、端末の処理能力を多く使います。途中で「計算停止」して、「再開」または「リセット」できます。</p><h3>記録データ</h3><p>「記録」を押すと、敵15体と、入力中のデッキ(表示中の提案デッキがあればそれも)を記録データに保存します(最大5件)。各記録の「現在に反映」で、その時の敵とデッキに戻せます。</p></section><section id="help-report"><h2><span class="help-num">07</span>協力報告書作成</h2><ol class="help-steps"><li>「列」「行」の − ＋ で、マスの数を決めます(最初は3列5行、最大12列20行)。</li><li>各マスの画像の部分を押してキャラを選び、下の欄に数値を入れます。</li><li>消すときは右上の「削除」を押します。各マスの削除ボタンと「全削除」が出ます。「削除終了」で元に戻ります。</li></ol><p>列・行の数を変えても、入っているキャラと数値の位置(何行目・何列目)は変わりません。減らして表の外に出たマスの中身は残っていて、増やし直すと元の位置に戻ります(「全削除」をすると、表の外の分も消えます)。キャラ画像はドラッグで別のマスと入れ替えられます。</p><p>でき上がった表は、端末のスクリーンショットで共有してください。</p></section><section id="help-data"><h2><span class="help-num">08</span>データの保存</h2><p>入力や記録は、サーバーではなく<b>このブラウザーの中</b>に保存されます。ページを開き直しても残りますが、別の端末・別のブラウザーには引き継がれません。ブラウザーのデータを消すと消えます。</p><dl class="help-dl"><dt>保存されるもの</dt><dd>お気に入りのキャラ、計算機の計算履歴と設定(詳細モード・解答速度・自力モード・問題レベル)、協力ダメージ計算の入力と記録データ、協力報告書。</dd></dl><p>別の端末やブラウザーへ移すときは、<button type="button" class="help-link" data-go="migration">データ移行</button>のページを使ってください。</p></section>`}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',renderComprehensiveHelp);else renderComprehensiveHelp();
